"""U02 cheap checks: Z0634 (subgroup generated by prime factors of 4Cp+1 mod 4C), Z0699 (fraction of U from the first
x-values), Z0694 (a_p of y^2=x^3-x and y^2=x^3+4x mod 8 vs (2/p)), Z0952 (U residual vs r_{x^2+ky^2}(n), composites)."""
import sys, json, math
import numpy as np
sys.path.insert(0, 'scripts')
from z52b_p1_U02_lib import esols
from sympy import primerange, factorint, isprime
out = {}
# Z0634
res634 = {}
P = [p for p in primerange(3, 20001) if p % 4 == 1]
def sub_gen(gens, m):
    H = {1 % m}
    for g in gens:
        g %= m
        new = set(H)
        frontier = list(H)
        # close under multiplication by g
        cur = set(H)
        while True:
            add = {(h * g) % m for h in cur} - cur
            if not add: break
            cur |= add
        H = cur
    return H
for C in range(1, 13):
    m = 4 * C
    neg1_out = 0; sizes = {}
    for p in P:
        N = 4 * C * p + 1
        qs = list(factorint(N).keys())
        gens = {q % m for q in qs}
        H = sub_gen(gens, m)
        sizes[len(H)] = sizes.get(len(H), 0) + 1
        if (m - 1) not in H: neg1_out += 1
    res634[C] = {'n_p': len(P), 'frac_minus1_not_in_H': round(neg1_out / len(P), 4), 'H_size_hist': dict(sorted(sizes.items()))}
out['Z0634'] = res634
# Z0699: among ES solutions for p = 1 mod 4 (p<=3000): share of solutions with x - ceil(p/4) in {0,1,2}
x_share = []
for p in [p for p in primerange(5, 3001) if p % 4 == 1]:
    S = esols(p)
    if not S: continue
    c = -(-p // 4)
    x_share.append((p, len(S), sum(1 for s in S if s[0] - c <= 2) / len(S)))
fr = np.array([t[2] for t in x_share])
out['Z0699_frac_first3x'] = {'n_p': len(x_share), 'mean': float(fr.mean()), 'median': float(np.median(fr)),
                             'min': float(fr.min())}
# Z0694: a_p for y^2 = x^3 - x and y^2 = x^3 + 4x mod 8 vs (2/p), p odd prime < 400
def ap(p, a4, a6=0):
    s = 0
    for x in range(p):
        r = (x**3 + a4*x + a6) % p
        s += 0 if r == 0 else (1 if pow(r, (p-1)//2, p) == 1 else -1)
    return -s
chk = {}
for name, a4 in (('x^3-x', -1), ('x^3+4x', 4)):
    vals = []
    for p in primerange(3, 400):
        a = ap(p, a4)
        leg2 = 1 if p % 8 in (1, 7) else -1
        vals.append((p, a, a % 8, leg2))
    chk[name] = {'frac_a_mod8_eq_leg2': round(sum(1 for v in vals if v[2] == v[3] % 8) / len(vals), 3),
                 'examples': vals[:8]}
out['Z0694'] = chk
# Z0952: correlate U(n) (composite n, from f4 data) with r_{x^2+k y^2}(n) for k = 1,2,3, after removing a log-n trend
F = np.loadtxt('/home/pasky/projects/math/erdos-straus-claude/data/z52b/raw/f4_all_30000.txt', dtype=np.int64)
Nmax = 30000
rk = {}
for k in (1, 2, 3):
    r = np.zeros(Nmax + 1, np.int64)
    xmax = int(math.isqrt(Nmax)) + 1
    for x in range(-xmax, xmax + 1):
        for y in range(-xmax, xmax + 1):
            v = x * x + k * y * y
            if v <= Nmax: r[v] += 1
    rk[k] = r
n_all = F[:, 0]; U = F[:, 1].astype(float)
isp = np.ones(Nmax + 1, bool); isp[:2] = False
for i in range(2, int(Nmax ** .5) + 1):
    if isp[i]: isp[i*i::i] = False
comp = (~isp[n_all]) & (n_all >= 50) & (U > 0)
nn = n_all[comp]; lu = np.log(U[comp]); lp = np.log(nn)
X = np.column_stack([np.ones_like(lp), lp, np.log(lp)])
res = lu - X @ np.linalg.lstsq(X, lu, rcond=None)[0]
out['Z0952'] = {'n_composite': int(comp.sum())}
for k in (1, 2, 3):
    rv = rk[k][nn].astype(float)
    out['Z0952'][f'corr_res_r{k}'] = float(np.corrcoef(res, rv)[0, 1])
    out['Z0952'][f'corr_res_logr{k}'] = float(np.corrcoef(res, np.log1p(rv))[0, 1])
json.dump(out, open('data/z52b/pass1/U02/cheap_b.json', 'w'), indent=1, default=float)
for k, v in out.items(): print(k, str(v)[:600])
